; ELF stub: hand-made header, unpacks the compressed payload in memory and calls it.
; Layout (single RWX PT_LOAD at BASE): headers | dynamic data | parameters | decoder | zero padding | compressed stream.
bits 64
%include "params.inc"          ; NM, A0, CAP, NS, TMASK, ACC0 and the PARAMS macro (generated by tools/cm/mkparams.py)
BASE    equ 0x400000
%ifndef DEST
%define DEST 0x401000          ; unpacked payload
%endif
%ifndef TABLE
%define TABLE 0x1000000        ; model slots (zero-filled bss)
%endif
%ifndef MEMSIZE
%define MEMSIZE 0x2000000-BASE
%endif
org BASE
ehdr:
  db 0x7f,'ELF',2,1,1,0
  times 8 db 0
  dw 2, 0x3e
  dd 1
  dq start
  dq phdr - ehdr
got:                            ; e_shoff (unused by the kernel): dlsym lands here
  dq 0
  dd 0
  dw 64, 56, 3, 0, 0, 0
phdr:
  dd 3, 4                                            ; PT_INTERP
  dq interp - ehdr, interp, interp, interp_end - interp, interp_end - interp, 1
  dd 1, 7                                            ; PT_LOAD  rwx
  dq 0, BASE, BASE, FILESIZE, MEMSIZE, 0x1000
  dd 2, 6                                            ; PT_DYNAMIC
  dq dynamic - ehdr, dynamic, dynamic, dynamic_end - dynamic, dynamic_end - dynamic, 8
interp: db "/lib64/ld-linux-x86-64.so.2",0
interp_end:
dynamic:
%ifdef LIBS
  LIBS_ENTRIES
%endif
  dq 5, strtab
  dq 6, symtab
  dq 7, rela
  dq 8, 24
  dq 9, 24
  dq 0, 0
dynamic_end:
strtab: db 0
%ifdef LIBS
  LIBS_NAMES
%endif
dlsym_name: db "dlsym",0
symtab:
  times 24 db 0
  dd dlsym_name - strtab
  db 0x12, 0
  dw 0
  dq 0, 0
rela:
  dq got
  dq (1<<32)|6
  dq 0
params: PARAMS
start:
  mov   ebx, TABLE
  mov   ebp, params
  mov   esi, stream
  mov   edi, DEST
  mov   r14d, DEST+PAYLEN
%include "dec4.inc"
  call  DEST
  times STREAMPOS-($-$$) db 0
stream:
  incbin STREAMFILE
FILESIZE equ $-ehdr
